```go
package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/micro/go-micro/codec/avro"
)

// Define your structure here (e.g., with `type MyStruct ...`)
type MyStruct struct {
	Field1 string `json:"field1"`
	Field2 int    `json:"field2"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <filename> <struct_name>")
		os.Exit(1)
	}

	filename := os.Args[1]
	structName := os.Args[2]

	// Read the Go source code
	content, err := ioutil.ReadFile(filename)
	if err != nil {
		fmt.Printf("Error reading file %s: %v\n", filename, err)
		return
	}

	// Parse the JSON content into the struct
	var myStruct MyStruct
	err = json.Unmarshal(content, &myStruct)
	if err != nil {
		fmt.Printf("Error unmarshalling JSON: %v\n", err)
		return
	}

	// Generate Avro schema
	schema, err := avro.Marshal(myStruct)
	if err != nil {
		fmt.Printf("Error generating Avro schema: %v\n", err)
		return
	}

	// Write the Avro schema to a file
	outFile, err := os.Create(structName + ".avsc")
	if err != nil {
		fmt.Printf("Error creating file %s.avsc: %v\n", structName, err)
		return
	}
	defer outFile.Close()

	_, err = outFile.Write(schema)
	if err != nil {
		fmt.Printf("Error writing Avro schema to file %s.avsc: %v\n", structName, err)
		return
	}

	fmt.Printf("Generated Avro schema written to %s.avsc\n", structName)
}
```

